<template>
	<button v-if="config?.enabled" class="account-trigger" type="button" :title="me?.authenticated ? `个人中心：${me.user.nickname}` : '账号未登录'" @click="openPanel">
		<span class="account-trigger__avatar"><img v-if="me?.authenticated && me.user.avatarUrl" :src="me.user.avatarUrl" alt=""/><span v-else-if="me?.authenticated">{{ String(me.user.nickname || me.user.username || "用").slice(0,1) }}</span><svg v-else viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.25"/><path d="M5.5 19c.55-3.55 2.75-5.5 6.5-5.5s5.95 1.95 6.5 5.5"/></svg></span><span>{{ me?.authenticated ? me.user.nickname : "未登录" }}</span>
	</button>
	<Teleport to="body"><Transition name="account-window"><div v-if="show" class="account-overlay" @click.self="show=false"><section class="account-panel" role="dialog" aria-modal="true" aria-label="个人中心">
		<header><div><strong>{{ me?.authenticated ? "个人中心" : "账号登录" }}</strong><small v-if="me?.authenticated">@{{ me.user.username }} · {{ me.user.role === "admin" ? "管理员" : "用户" }}</small></div><button class="icon-button" title="关闭" @click="show=false"><svg viewBox="0 0 20 20"><path d="m5 5 10 10M15 5 5 15"/></svg></button></header>
		<template v-if="!me?.authenticated">
			<nav class="account-tabs"><button :class="{active:mode==='login'}" @click="mode='login'">登录</button><button v-if="config?.registrationEnabled" :class="{active:mode==='register'}" @click="mode='register'">注册</button><button :class="{active:mode==='reset'}" @click="mode='reset'">重置密码</button></nav>
			<Transition name="account-content" mode="out-in"><form :key="mode" class="account-form" @submit.prevent="submitAuth">
				<div v-if="mode==='login'" class="segmented"><button type="button" :class="{active:loginMethod==='password'}" @click="loginMethod='password'">密码登录</button><button type="button" :class="{active:loginMethod==='code'}" @click="loginMethod='code'">邮箱验证码</button></div>
				<template v-if="mode==='register'"><label>用户名<small>用于登录，只能使用字母、数字、下划线和连字符</small><input v-model.trim="registerForm.username" pattern="[A-Za-z0-9_-]{3,32}" minlength="3" maxlength="32" autocomplete="username" required/></label><label>昵称<small>显示给其他用户，登录后仍可修改</small><input v-model.trim="registerForm.nickname" maxlength="80" required/></label><label>邮箱<input v-model.trim="registerForm.email" type="email" autocomplete="email" required/></label><label>密码<input v-model="registerForm.password" type="password" minlength="10" autocomplete="new-password" required/></label><CodeField v-model="registerForm.code" label="邮件验证码" :hint="mailHint" @send="requestCode('register',registerForm.email,registerForm)"/></template>
				<template v-else-if="mode==='reset'"><label>邮箱<input v-model.trim="resetForm.email" type="email" required/></label><label>新密码<input v-model="resetForm.password" type="password" minlength="10" required/></label><CodeField v-model="resetForm.code" label="邮件验证码" :hint="mailHint" @send="requestCode('reset-password',resetForm.email,resetForm)"/></template>
				<template v-else-if="loginMethod==='code'"><label>邮箱<input v-model.trim="loginCodeForm.email" type="email" autocomplete="email" required/></label><CodeField v-model="loginCodeForm.code" label="邮件验证码" hint="验证码可直接登录，无需密码；若未收到，也请检查垃圾邮件或广告邮件。" @send="requestCode('login',loginCodeForm.email,loginCodeForm)"/></template>
				<template v-else><label>用户名或邮箱<input v-model.trim="loginForm.identity" autocomplete="username" required/></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" required/></label><CodeField v-if="needsCode" v-model="loginForm.code" label="新设备邮件验证码" :hint="mailHint" @send="requestCode('login',loginVerificationEmail,loginForm)"/></template>
				<p v-if="error" class="notice" :class="{success:noticeSuccess}">{{ error }}</p><button class="primary submit" :disabled="busy">{{ busy ? "处理中…" : mode==='register' ? "注册并登录" : mode==='reset' ? "重置密码" : "登录" }}</button>
			</form></Transition>
		</template>
		<form v-else-if="me.user.mustChangePassword" class="account-form" @submit.prevent="completeInitialCredentials"><h3>更换初始管理员凭据</h3><p>保存后配置文件里的初始用户名和密码会立即失效。</p><label>正式用户名<small>3–32 位，只能使用字母、数字、_ 和 -</small><input v-model.trim="initialForm.username" pattern="[A-Za-z0-9_-]{3,32}" required/></label><label>昵称<input v-model.trim="initialForm.nickname" maxlength="80" required/></label><label>正式邮箱<input v-model.trim="initialForm.email" type="email" required/></label><label>当前初始密码<input v-model="initialForm.currentPassword" type="password" required/></label><label>新密码<input v-model="initialForm.password" type="password" minlength="10" required/></label><p v-if="error" class="notice">{{ error }}</p><button class="primary submit">保存并重新登录</button></form>
		<template v-else>
			<nav class="account-tabs center-tabs"><button :class="{active:section==='profile'}" @click="section='profile'">个人资料</button><button :class="{active:section==='projects'}" @click="section='projects';loadProjects()">云端工程</button><button :class="{active:section==='security'}" @click="section='security'">账号安全</button></nav>
			<Transition name="account-content" mode="out-in">
				<form v-if="section==='profile'" key="profile" class="account-form" @submit.prevent="saveProfile"><div class="profile-avatar"><span><img v-if="profileForm.avatarUrl" :src="profileForm.avatarUrl" alt="头像预览"/><b v-else>{{ String(profileForm.nickname||me.user.username).slice(0,1) }}</b></span><div><strong>{{ profileForm.nickname||me.user.username }}</strong><small>@{{ me.user.username }}</small><button type="button" @click="avatarInput?.click()">上传头像</button><input ref="avatarInput" class="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif" @change="uploadProfileAvatar"/></div></div><label>用户名<input :value="me.user.username" disabled/><small>用户名用于登录，注册后不可修改。</small></label><label>昵称<input v-model.trim="profileForm.nickname" maxlength="80" required/></label><label>头像 HTTPS 链接<input v-model.trim="profileForm.avatarUrl" type="url" placeholder="也可以直接填写图片链接"/></label><label>邮箱<div class="inline"><input v-model.trim="profileForm.email" type="email" required/><button v-if="profileForm.email!==me.user.email" type="button" @click="requestCode('change-email',profileForm.email,profileForm)">验证新邮箱</button></div></label><label v-if="profileForm.email!==me.user.email">新邮箱验证码<input v-model.trim="profileForm.code" inputmode="numeric" maxlength="6" required/><small class="mail-hint">{{ mailHint }}</small></label><p v-if="error" class="notice" :class="{success:noticeSuccess}">{{ error }}</p><button class="primary submit" :disabled="busy">保存个人资料</button></form>
				<section v-else-if="section==='projects'" key="projects" class="projects"><div class="project-actions"><button class="primary" @click="saveCurrent">{{ currentProject ? "保存当前工程修订" : "保存当前记录到云端" }}</button><button v-if="currentProject" @click="currentProject=null">另存为</button><button @click="loadProjects">刷新</button></div><p v-if="!projects.length">暂时没有云端工程。</p><article v-for="project in projects" :key="project.id"><div><strong>{{ project.title }}</strong><small>修订 {{ project.revision }} · {{ new Date(project.updatedAt).toLocaleString() }}</small></div><button @click="openProject(project.id)">打开</button><button v-if="project.sourceKey" @click="syncProject(project.id)">同步</button><button class="danger" @click="deleteProject(project.id)">删除</button></article></section>
				<form v-else key="security" class="account-form" @submit.prevent="changePassword"><h3>修改密码</h3><label>当前密码<input v-model="passwordForm.current" type="password" required/></label><label>新密码<input v-model="passwordForm.next" type="password" minlength="10" required/></label><p v-if="error" class="notice">{{ error }}</p><button class="primary submit">修改密码并重新登录</button></form>
			</Transition>
			<footer class="account-footer"><a href="/docs">使用文档</a><a v-if="me.user.role==='admin'" href="/admin">账户与日志管理</a><button @click="logout">退出登录</button></footer>
		</template>
	</section></div></Transition></Teleport>
	<Teleport to="body"><Transition name="account-window"><div v-if="captcha.show" class="captcha-overlay" @click.self="captcha.show=false"><section role="dialog" aria-modal="true"><h3>人机验证</h3><p>发送邮件或异常行为需要先验证。</p><div v-if="captcha.provider==='image'"><div class="captcha-image" v-html="captcha.image"></div><input v-model="captcha.answer" placeholder="输入图中的字符" autocomplete="off"/></div><altcha-widget v-else-if="captcha.provider==='altcha'" ref="altchaEl" language="zh-cn" workers="1" @statechange="onAltchaState"/><div v-else ref="externalCaptcha"></div><p class="mail-hint">验证邮件可能被归类为垃圾邮件或广告邮件，请同时检查这些文件夹。</p><p v-if="captcha.error" class="notice">{{ captcha.error }}</p><footer><button @click="captcha.show=false">取消</button><button v-if="captcha.provider==='image'" class="primary" @click="verifyCaptcha">验证</button></footer></section></div></Transition></Teleport>
</template>

<script setup lang="ts">
import "altcha";
import { defineComponent, h, nextTick, onMounted, reactive, ref } from "vue";
import { storyFromLogItems } from "~/story/model";
import { parseStoryScript, serializeStoryScript } from "~/story/raw-script";
import type { StoryArchive } from "~/story/types";

const CodeField=defineComponent({props:{modelValue:{type:String,required:true},label:{type:String,required:true},hint:{type:String,default:""}},emits:["update:modelValue","send"],setup(props,{emit}){return()=>h("label",{class:"code-field"},[props.label,h("div",{class:"code-field__row"},[h("input",{class:"code-field__input",value:props.modelValue,inputmode:"numeric",autocomplete:"one-time-code",maxlength:6,placeholder:"请输入 6 位验证码",onInput:(event:Event)=>emit("update:modelValue",(event.target as HTMLInputElement).value)}),h("button",{class:"code-field__send",type:"button",onClick:()=>emit("send")},"发送验证码")]),props.hint?h("small",{class:"mail-hint"},props.hint):null])}});
const props=defineProps<{archive?:StoryArchive}>();const emit=defineEmits<{load:[StoryArchive];sync:[any]}>();
type Config={enabled:boolean;registrationEnabled:boolean;captchaProvider:string;turnstileSiteKey:string;hcaptchaSiteKey:string};type Me={authenticated:boolean;user:any};type CodeForm={codeId:string;code:string;[key:string]:unknown};
const mailHint="若几分钟内没有收到，请同时检查垃圾邮件或广告邮件。";
const show=ref(false),config=ref<Config>(),me=ref<Me>(),mode=ref<"login"|"register"|"reset">("login"),loginMethod=ref<"password"|"code">("password"),section=ref<"profile"|"projects"|"security">("profile"),busy=ref(false),error=ref(""),noticeSuccess=ref(false),needsCode=ref(false),loginVerificationEmail=ref(""),projects=ref<any[]>([]),currentProject=ref<{id:string;revision:number}|null>(null),altchaEl=ref<any>(),externalCaptcha=ref<HTMLElement>(),avatarInput=ref<HTMLInputElement>();
const loginForm=reactive({identity:"",password:"",code:"",codeId:""}),loginCodeForm=reactive({email:"",code:"",codeId:""}),registerForm=reactive({email:"",username:"",nickname:"",password:"",code:"",codeId:""}),resetForm=reactive({email:"",password:"",code:"",codeId:""}),profileForm=reactive({email:"",nickname:"",avatarUrl:"",code:"",codeId:""}),passwordForm=reactive({current:"",next:""}),initialForm=reactive({username:"",nickname:"",email:"",currentPassword:"",password:""});
const captcha=reactive({show:false,id:"",provider:"image",image:"",answer:"",payload:"",token:"",error:"",purpose:"login",scope:"verification-send",email:"",username:"",nickname:""});let pendingRetry:(()=>Promise<void>)|null=null;let codeTarget:CodeForm|null=null;
function openPanel(){show.value=true;error.value="";if(me.value?.authenticated){section.value="profile";hydrateProfile()}}function csrf(){return decodeURIComponent(document.cookie.split("; ").find(value=>value.startsWith("scardice_account_csrf="))?.split("=").slice(1).join("=")||"")}
async function request(path:string,options:RequestInit={}){const headers=new Headers(options.headers);if(options.body)headers.set("Content-Type","application/json");const token=csrf();if(token)headers.set("X-CSRF-Token",token);const response=await fetch(path,{...options,headers,credentials:"same-origin"});const data=await response.json().catch(()=>({error:"invalid_response"}));if(!response.ok){const exception:any=new Error(data.error||"request_failed");exception.data=data;exception.status=response.status;throw exception}return data}
function readable(value:any){const data=value?.data||{};if(data.error==="account_banned")return`账号已被封禁：${data.reason||"未提供原因"}${data.until?`（至 ${data.until}）`:""}`;const map:any={invalid_credentials:"用户名、邮箱或密码不正确",email_verification_required:"这是新设备或新网段，请完成邮件验证",verification_invalid:"验证码不正确或已过期",smtp_not_configured:"管理员尚未配置 SMTP",captcha_required:"请先完成人机验证",account_exists:"用户名或邮箱已经存在",registration_unavailable:"该邮箱无法注册",invalid_registration:"请检查用户名、昵称、邮箱和密码格式",reset_invalid:"重置资料或验证码无效",initial_credentials_invalid:"请检查初始密码、正式邮箱、用户名、昵称与新密码",profile_invalid:"个人资料格式不正确"};return map[data.error||value?.message]||"操作失败，请稍后重试"}
function hydrateProfile(){if(!me.value?.authenticated)return;Object.assign(profileForm,{email:me.value.user.email||"",nickname:me.value.user.nickname||me.value.user.displayName||"",avatarUrl:me.value.user.avatarUrl||"",code:"",codeId:""})}async function refreshMe(){me.value=await request("/api/account/me");if(me.value?.authenticated){const user=me.value.user;Object.assign(initialForm,{username:user.username||"",nickname:user.nickname||user.displayName||"",email:String(user.email||"").endsWith("@bootstrap.invalid")?"":user.email||""});hydrateProfile();if(!user.mustChangePassword)loadProjects()}}function acceptAuthenticatedUser(user:any){me.value={authenticated:true,user};error.value="";if(user.mustChangePassword)Object.assign(initialForm,{username:user.username||"",nickname:user.nickname||user.displayName||"",email:String(user.email||"").endsWith("@bootstrap.invalid")?"":user.email||""});else{hydrateProfile();section.value="profile";loadProjects()}}
async function submitAuth(){busy.value=true;error.value="";noticeSuccess.value=false;try{if(mode.value==="register"){acceptAuthenticatedUser((await request("/api/account/register",{method:"POST",body:JSON.stringify(registerForm)})).user)}else if(mode.value==="reset"){await request("/api/account/password/reset",{method:"POST",body:JSON.stringify(resetForm)});mode.value="login";error.value="密码已重置，请重新登录";noticeSuccess.value=true}else if(loginMethod.value==="code")acceptAuthenticatedUser((await request("/api/account/login/code",{method:"POST",body:JSON.stringify(loginCodeForm)})).user);else acceptAuthenticatedUser((await request("/api/account/login",{method:"POST",body:JSON.stringify({email:loginForm.identity,password:loginForm.password,codeId:loginForm.codeId,code:loginForm.code})})).user)}catch(exception:any){if(exception.data?.error==="email_verification_required"){needsCode.value=true;loginVerificationEmail.value=String(exception.data.email||"")}if(exception.data?.error==="captcha_required")await beginCaptcha(String(exception.data.scope||"login"),submitAuth);error.value=readable(exception)}finally{busy.value=false}}
async function requestCode(purpose:string,email:string,target:CodeForm){if(!email){error.value="请先填写邮箱";return}captcha.purpose=purpose;captcha.email=email;captcha.username=registerForm.username;captcha.nickname=registerForm.nickname;codeTarget=target;await beginCaptcha("verification-send")}async function beginCaptcha(scope:string,retry:(()=>Promise<void>)|null=null){captcha.scope=scope;pendingRetry=retry;captcha.error="";const challenge=await request("/api/account/captcha/challenge",{method:"POST",body:"{}"});Object.assign(captcha,{show:true,id:challenge.id,provider:challenge.provider,image:challenge.image||"",answer:"",payload:"",token:""});await nextTick();if(challenge.provider==="altcha")altchaEl.value?.configure?.({challenge:challenge.challenge,workers:1,language:"zh-cn"});else if(challenge.provider==="turnstile"||challenge.provider==="hcaptcha")renderExternal(challenge.provider,challenge.siteKey)}
async function renderExternal(provider:string,siteKey:string){const globalName=provider==="turnstile"?"turnstile":"hcaptcha",src=provider==="turnstile"?"https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit":"https://js.hcaptcha.com/1/api.js?render=explicit";if(!(globalThis as any)[globalName])await new Promise<void>((resolve,reject)=>{const script=document.createElement("script");script.src=src;script.async=true;script.onload=()=>resolve();script.onerror=()=>reject();document.head.append(script)});await nextTick();(globalThis as any)[globalName].render(externalCaptcha.value,{sitekey:siteKey,callback:(token:string)=>{captcha.token=token;verifyCaptcha()}})}function onAltchaState(event:CustomEvent){if(event.detail?.state==="verified"){captcha.payload=event.detail.payload;verifyCaptcha()}}
async function verifyCaptcha(){try{captcha.error="";const data=await request("/api/account/captcha/verify",{method:"POST",body:JSON.stringify({id:captcha.id,answer:captcha.answer,payload:captcha.payload,token:captcha.token,email:captcha.email||loginVerificationEmail.value,scope:captcha.scope})});if(captcha.scope!=="verification-send"){captcha.show=false;const retry=pendingRetry;pendingRetry=null;if(retry)await retry();return}const sent=await request("/api/account/verification/send",{method:"POST",body:JSON.stringify({email:captcha.email,purpose:captcha.purpose,username:captcha.username,nickname:captcha.nickname,captchaClearance:data.clearance})});if(codeTarget)codeTarget.codeId=sent.id;captcha.show=false;error.value="验证码已发送；若未收到，请检查垃圾邮件或广告邮件";noticeSuccess.value=true}catch(exception){captcha.error=readable(exception)}}
async function uploadProfileAvatar(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;try{const response=await fetch("/api/editor/resources",{method:"POST",headers:{"Content-Type":file.type||"application/octet-stream","X-Resource-Kind":"image"},body:await file.arrayBuffer()}),result=await response.json();if(!response.ok)throw new Error(result.error||"upload_failed");profileForm.avatarUrl=result.url;error.value="头像已压缩并暂存，保存资料后生效";noticeSuccess.value=true}catch{error.value="头像上传失败"}finally{busy.value=false;if(avatarInput.value)avatarInput.value.value=""}}async function saveProfile(){busy.value=true;error.value="";try{const data=await request("/api/account/profile",{method:"PATCH",body:JSON.stringify(profileForm)});me.value={authenticated:true,user:data.user};hydrateProfile();error.value="个人资料已保存";noticeSuccess.value=true}catch(exception:any){if(exception.data?.error==="captcha_required")await beginCaptcha(exception.data.scope||"profile-change",saveProfile);error.value=readable(exception);noticeSuccess.value=false}finally{busy.value=false}}
function bytesToBase64(bytes:Uint8Array){let value="";for(let index=0;index<bytes.length;index+=0x8000)value+=String.fromCharCode(...bytes.subarray(index,index+0x8000));return btoa(value)}function packArchive(){if(!props.archive)return null;return{language:serializeStoryScript(props.archive),assets:[...props.archive.assets].map(([id,bytes])=>[id,bytesToBase64(bytes)])}}function unpackArchive(value:any):StoryArchive{if(typeof value?.language!=="string")throw new Error("该云端工程不是 Lorana Tales Story Language 格式");const assets=new Map<string,Uint8Array>((value.assets||[]).map(([id,text]:[string,string])=>[id,Uint8Array.from(atob(text),character=>character.charCodeAt(0))]));const base=props.archive||{document:storyFromLogItems([],[],{title:"故事",assets}),assets};return parseStoryScript(value.language,{document:base.document,assets})}
async function loadProjects(){if(!me.value?.authenticated)return;try{projects.value=await request("/api/account/projects")}catch{projects.value=[]}}async function saveCurrent(){const packed=packArchive();if(!packed)return;try{const base={title:props.archive?.document.title,document:packed,sourceKey:props.archive?.document.source.key||"",sourceRevision:props.archive?.document.source.revision||"",sourceSecret:props.archive?.document.source.key?location.hash.slice(1):""},saved=currentProject.value?await request(`/api/account/projects/${encodeURIComponent(currentProject.value.id)}`,{method:"PUT",body:JSON.stringify({...base,revision:currentProject.value.revision})}):await request("/api/account/projects",{method:"POST",body:JSON.stringify(base)});currentProject.value={id:saved.id,revision:saved.revision};await loadProjects()}catch(exception:any){if(exception.data?.error==="captcha_required")await beginCaptcha(exception.data.scope||"project-write",saveCurrent);error.value=readable(exception)}}async function openProject(id:string){try{const project=await request(`/api/account/projects/${encodeURIComponent(id)}`);currentProject.value={id:project.id,revision:project.revision};emit("load",unpackArchive(project.document));show.value=false}catch(exception){error.value=readable(exception)}}async function syncProject(id:string){try{emit("sync",await request(`/api/account/projects/${encodeURIComponent(id)}/source`));show.value=false}catch{error.value="源日志已失效、密钥不正确或不可访问"}}async function deleteProject(id:string){if(!confirm("确定删除这个云端工程吗？"))return;try{await deleteProjectConfirmed(id)}catch(exception:any){if(exception.data?.error==="captcha_required")await beginCaptcha(exception.data.scope||"project-delete",()=>deleteProjectConfirmed(id));error.value=readable(exception)}}async function deleteProjectConfirmed(id:string){await request(`/api/account/projects/${encodeURIComponent(id)}`,{method:"DELETE"});if(currentProject.value?.id===id)currentProject.value=null;await loadProjects()}
async function changePassword(){try{await request("/api/account/password",{method:"POST",body:JSON.stringify({currentPassword:passwordForm.current,password:passwordForm.next})});me.value={authenticated:false,user:null};mode.value="login";error.value="密码已修改，请重新登录";noticeSuccess.value=true}catch(exception:any){if(exception.data?.error==="captcha_required")await beginCaptcha(exception.data.scope||"password-change",changePassword);error.value=readable(exception)}}async function logout(){try{await request("/api/account/logout",{method:"POST",body:"{}"})}finally{me.value={authenticated:false,user:null};mode.value="login"}}async function completeInitialCredentials(){error.value="";try{await request("/api/account/bootstrap/complete",{method:"POST",body:JSON.stringify(initialForm)});me.value={authenticated:false,user:null};mode.value="login";loginForm.identity=initialForm.email;error.value="初始凭据已废止，请使用新用户名、邮箱或密码重新登录。";noticeSuccess.value=true}catch(exception){error.value=readable(exception)}}onMounted(async()=>{try{config.value=await request("/api/account/config");await refreshMe()}catch{config.value={enabled:false,registrationEnabled:false,captchaProvider:"image",turnstileSiteKey:"",hcaptchaSiteKey:""}}});
